<script setup lang="ts">import type{Series}from '../types/domain';import{number}from '../utils/format';defineProps<{items:Series[]}>();defineEmits(['select']);</script><template><div class="table-wrap"><table><thead><tr><th>日配序列</th><th>城市 / 品类</th><th>观测日数</th><th>需求合计</th><th></th></tr></thead><tbody><tr v-for="s in items" :key="s.id"><td><strong>{{s.name}}</strong><small>{{s.code}}</small></td><td>{{s.city}} / {{s.product}}</td><td>{{s.observation_count}} 天</td><td>{{number(s.total_demand)}} {{s.unit}}</td><td><button class="text" @click="$emit('select',s.id)">查看序列 ↗</button></td></tr></tbody></table></div></template>
